package com.bank.listing.repository;

import com.bank.listing.dto.TradeOverview;
import com.bank.listing.model.Trade;
import com.bank.listing.projection.TradeIdAndSymbol;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface TradeRepository extends JpaRepository<Trade, String> {

    // ═══ INTERFACE PROJECTION ═══
    List<TradeIdAndSymbol> findByStatus(String status);
    // SQL: SELECT trade_id, symbol FROM trades WHERE status = ?

    // ═══ DTO PROJECTION with JPQL constructor ═══
    @Query("SELECT new com.bank.listing.dto.TradeOverview(t.tradeId, t.symbol, t.amount) " +
           "FROM Trade t WHERE t.status = :status")
    List<TradeOverview> findOverviewByStatus(@Param("status") String status);
    // SQL: SELECT trade_id, symbol, amount FROM trades WHERE status = ?

    // ═══ DYNAMIC PROJECTION ═══
    <T> List<T> findByAccountId(String accountId, Class<T> type);
    // SQL depends on which Class<T> is passed!
}
```

