package com.bank.listing.service;

import com.bank.listing.dto.TradeOverview;
import com.bank.listing.model.Trade;
import com.bank.listing.projection.TradeIdAndSymbol;
import com.bank.listing.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class TradeListingService {

    private final TradeRepository tradeRepo;

    // ═══ 1. FULL ENTITY — all 12 columns, persistence context managed ═══
    @Transactional(readOnly = true)
    public List<Trade> getFullEntities(String status) {
        List<Trade> trades = tradeRepo.findAll();
        log.info("[FULL ENTITY] {} trades, ALL 12 columns loaded, persistence context manages each",
            trades.size());
        return trades;
    }

    // ═══ 2. INTERFACE PROJECTION — 2 columns, proxy ═══
    @Transactional(readOnly = true)
    public List<TradeIdAndSymbol> getInterfaceProjection(String status) {
        List<TradeIdAndSymbol> trades = tradeRepo.findByStatus(status);
        log.info("[INTERFACE] {} trades, 2 columns only (trade_id, symbol), proxy objects", trades.size());
        return trades;
    }

    // ═══ 3. DTO PROJECTION — 3 columns, plain record, FASTEST ═══
    @Transactional(readOnly = true)
    public List<TradeOverview> getDtoProjection(String status) {
        List<TradeOverview> trades = tradeRepo.findOverviewByStatus(status);
        log.info("[DTO] {} trades, 3 columns only (trade_id, symbol, amount), plain records — FASTEST",
            trades.size());
        return trades;
    }

    // ═══ 4. DYNAMIC — caller chooses projection ═══
    @Transactional(readOnly = true)
    public <T> List<T> getDynamic(String accountId, Class<T> type) {
        List<T> trades = tradeRepo.findByAccountId(accountId, type);
        log.info("[DYNAMIC] {} trades as {}", trades.size(), type.getSimpleName());
        return trades;
    }
}
