// ─── File: src/main/java/com/bank/listing/controller/TradeListController.java ───
package com.bank.listing.controller;

import com.bank.listing.dto.TradeOverview;
import com.bank.listing.projection.TradeIdAndSymbol;
import com.bank.listing.service.TradeListingService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/v1/trades")
@RequiredArgsConstructor
public class TradeListController {

    private final TradeListingService service;

    @GetMapping("/interface")
    public List<TradeIdAndSymbol> interfaceProjection(@RequestParam(defaultValue = "SETTLED") String status) {
        return service.getInterfaceProjection(status);
    }

    @GetMapping("/dto")
    public List<TradeOverview> dtoProjection(@RequestParam(defaultValue = "SETTLED") String status) {
        return service.getDtoProjection(status);
    }

    @GetMapping("/dynamic/{accountId}")
    public List<TradeOverview> dynamic(@PathVariable String accountId) {
        return service.getDynamic(accountId, TradeOverview.class);
    }
}
