// ─── File: src/test/java/com/bank/listing/service/ProjectionTest.java ───
package com.bank.listing.service;

import com.bank.listing.dto.TradeOverview;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class ProjectionTest {

    @Test
    void dtoRecordHasOnlyNeededFields() {
        TradeOverview dto = new TradeOverview("TRD-001", "RELIANCE", new BigDecimal("245050"));
        assertThat(dto.tradeId()).isEqualTo("TRD-001");
        assertThat(dto.symbol()).isEqualTo("RELIANCE");
        assertThat(dto.amount()).isEqualByComparingTo("245050");
        // No accountId, no notes, no auditTrail — not fetched, not stored!
    }

    @Test
    void dtoRecordAutoGeneratesEqualsHashCode() {
        TradeOverview a = new TradeOverview("TRD-001", "RELIANCE", new BigDecimal("245050"));
        TradeOverview b = new TradeOverview("TRD-001", "RELIANCE", new BigDecimal("245050"));
        assertThat(a).isEqualTo(b);
        assertThat(a.hashCode()).isEqualTo(b.hashCode());
    }

    @Test
    void interfaceProjectionDefinesContract() {
        // Interface-based projection is just an interface — Spring generates proxy
        // The proxy intercepts getTradeId() and getSymbol() calls
        // and returns the corresponding column values from the result set
        assertThat(true).isTrue();  // conceptual — requires Spring context for proxy
    }

    @Test
    void performanceRanking() {
        // 1. DTO/record: fewest columns, no proxy, no persistence context → FASTEST
        // 2. Interface: few columns, proxy overhead → FAST
        // 3. Full entity: all columns, persistence context, dirty checking → SLOWEST

        // For a table with 15 columns and 50K rows:
        // Full entity: 15 columns × 50K = 750K field reads + 50K snapshots
        // DTO (3 fields): 3 columns × 50K = 150K field reads, zero snapshots
        // Savings: 80% less data transferred + zero persistence context memory

        int fullEntityFields = 15 * 50000;
        int dtoFields = 3 * 50000;
        double savings = 1.0 - ((double) dtoFields / fullEntityFields);
        assertThat(savings).isGreaterThan(0.7);  // >70% less data
    }
}
```
